// ignore_for_file: avoid_print
import 'dart:convert';
import 'dart:io';

class RawSentence {
  final String id;
  final String text;
  final String meaning;
  final String difficulty;
  final String category;
  final List<Map<String, String>> vocabulary;

  RawSentence({
    required this.id,
    required this.text,
    required this.meaning,
    required this.difficulty,
    required this.category,
    required this.vocabulary,
  });

  Map<String, dynamic> toJson() => {
        'id': id,
        'text': text,
        'meaning': meaning,
        'difficulty': difficulty,
        'category': category,
        'vocabularyWords': vocabulary,
      };
}

void main() {
  print('Generating 600 unique English sentences...');

  final allSentences = <RawSentence>[];

  // Helper to add sentence and check duplicate
  final seenTexts = <String>{};
  final seenIds = <String>{};

  void add(RawSentence s) {
    final normText = s.text.trim().toLowerCase();
    if (seenTexts.contains(normText)) {
      throw Exception('Duplicate text found: "${s.text}"');
    }
    if (seenIds.contains(s.id)) {
      throw Exception('Duplicate ID found: "${s.id}"');
    }
    seenTexts.add(normText);
    seenIds.add(s.id);
    allSentences.add(s);
  }

