    ['The treaty establishes rigorous verification protocols to deter covert nuclear proliferation and stockpile modernization.', 'Global inspectors ensuring secret atomic weapons are not built.', 'Everyday English', 'Proliferation', 'Rapid increase in the number or amount of something; spread of weapons', 'Verification', 'The process of establishing the truth, accuracy, or validity of something'],
    ['Linguistic determinism posited that the grammatical structure of a mother tongue decisively shapes conceptual perception.', 'The theory that the language you speak determines the very way your brain thinks.', 'School', 'Linguistic', 'Relating to language or linguistics', 'Determinism', 'The doctrine that events are determined by causes external to the will'],
  ];

  final int neededAdvanced = 200 - allSentences.where((s) => s.difficulty == 'Advanced').length;
  for (int i = 0; i < neededAdvanced && i < extraAdvanced.length; i++) {
    final row = extraAdvanced[i];
    final currentAdvCount = allSentences.where((s) => s.difficulty == 'Advanced').length;
    final numStr = (currentAdvCount + 1).toString().padLeft(3, '0');
    add(RawSentence(
      id: 'a$numStr',
      text: row[0],
      meaning: row[1],
      category: row[2],
      difficulty: 'Advanced',
      vocabulary: [
        {'word': row[3], 'meaning': row[4]},
        {'word': row[5], 'meaning': row[6]},
      ],
    ));
  }

  print('Final total sentences: ${allSentences.length}');
  final bCount = allSentences.where((s) => s.difficulty == 'Beginner').length;
  final iCount = allSentences.where((s) => s.difficulty == 'Intermediate').length;
  final aCount = allSentences.where((s) => s.difficulty == 'Advanced').length;
  print('Beginner: $bCount, Intermediate: $iCount, Advanced: $aCount');

  // Validate 0 duplicates
  assert(allSentences.length == 600, 'Expected exactly 600 sentences, got ${allSentences.length}');
  assert(bCount == 200, 'Expected 200 Beginner sentences, got $bCount');
  assert(iCount == 200, 'Expected 200 Intermediate sentences, got $iCount');
  assert(aCount == 200, 'Expected 200 Advanced sentences, got $aCount');

  // Now generate files:
  // 1. lib/data/sentences/beginner_sentences.dart
  // 2. lib/data/sentences/intermediate_sentences.dart
  // 3. lib/data/sentences/advanced_sentences.dart
  // 4. lib/data/sentences_data.dart
  // 5. assets/data/sentences.json

  Directory('lib/data/sentences').createSync(recursive: true);
  Directory('assets/data').createSync(recursive: true);

  String toDartCode(List<RawSentence> list, String varName) {
    final buf = StringBuffer();
    buf.writeln("import '../../models/sentence.dart';\n");
    buf.writeln("/// Static collection of ${list.length} sentences");
    buf.writeln("const List<Sentence> $varName = [");
    for (final s in list) {
      buf.writeln("  Sentence(");
      buf.writeln("    id: '${s.id}',");
      buf.writeln("    text: ${jsonEncode(s.text)},");
      buf.writeln("    meaning: ${jsonEncode(s.meaning)},");
      buf.writeln("    difficulty: '${s.difficulty}',");
      buf.writeln("    category: '${s.category}',");
      buf.writeln("    vocabularyWords: [");
      for (final v in s.vocabulary) {
        buf.writeln("      SentenceWord(word: ${jsonEncode(v['word'])}, meaning: ${jsonEncode(v['meaning'])}),");
      }
      buf.writeln("    ],");
      buf.writeln("  ),");
    }
    buf.writeln("];\n");
    return buf.toString();
  }

  final bList = allSentences.where((s) => s.difficulty == 'Beginner').toList();
  final iList = allSentences.where((s) => s.difficulty == 'Intermediate').toList();
  final aList = allSentences.where((s) => s.difficulty == 'Advanced').toList();

  File('lib/data/sentences/beginner_sentences.dart').writeAsStringSync(toDartCode(bList, 'beginnerSentences'));
  File('lib/data/sentences/intermediate_sentences.dart').writeAsStringSync(toDartCode(iList, 'intermediateSentences'));
  File('lib/data/sentences/advanced_sentences.dart').writeAsStringSync(toDartCode(aList, 'advancedSentences'));

  // Master sentences_data.dart
  final masterBuf = StringBuffer();
  masterBuf.writeln("import '../models/sentence.dart';");
  masterBuf.writeln("import 'sentences/beginner_sentences.dart';");
  masterBuf.writeln("import 'sentences/intermediate_sentences.dart';");
  masterBuf.writeln("import 'sentences/advanced_sentences.dart';\n");
  masterBuf.writeln("/// Complete collection of 600 unique offline English sentences (200 Beginner, 200 Intermediate, 200 Advanced)");
  masterBuf.writeln("class SentencesData {");
  masterBuf.writeln("  static const List<Sentence> sentences = [");
  masterBuf.writeln("    ...beginnerSentences,");
  masterBuf.writeln("    ...intermediateSentences,");
  masterBuf.writeln("    ...advancedSentences,");
  masterBuf.writeln("  ];");
  masterBuf.writeln("}\n");
  File('lib/data/sentences_data.dart').writeAsStringSync(masterBuf.toString());

  // assets/data/sentences.json
  final jsonList = allSentences.map((s) => s.toJson()).toList();
  File('assets/data/sentences.json').writeAsStringSync(const JsonEncoder.withIndent('  ').convert(jsonList));

  print('Successfully generated 600 unique sentences across all files!');
}
